const READS = {
  es: f => f.sInit ? 'E' + f.s : null,
  pt: f => f.sInit ? 'E' + f.s : (f.finalStop ? f.s + 'i' : null),
  tr: f => f.sInit ? 'İ' + f.s : null,
  hi: f => f.sInit ? 'I' + f.s : null,
  fi: f => { if (!f.initCluster) return null; let k = 0; while (k < f.s.length && !'aeiouy'.includes(f.s[k])) k++; return f.s.slice(Math.max(0, k - 1)); },
  ar: f => (f.p || f.v) ? f.s.replace(/p(?!h)/g,'b').replace(/v/g,'f') : null,
  de: f => f.w ? f.s.replace(/w/g,'v') : null,
  hu: f => f.sHu ? f.s.replace(/sz/g,'\u0001').replace(/s(?!h)/g,'sh').replace(/\u0001/g,'s') : null
};

function pronounce(raw){
  const f = features(raw), out = {};
  for (const L of LANGS){
    if (f.initialism){
      out[L.code] = {ease:85, issues:[{pen:15, text:'Read letter by letter. The letter names change by language; see the landmine scan for spelled-aloud results.'}], reads:null};
      continue;
    }
    const issues = [];
    for (const r of (PHONO_RULES[L.code] || [])){
      if (!r.test(f)) continue;
      const pen = typeof r.pen === 'function' ? r.pen(f) : r.pen;
      if (pen > 0) issues.push({pen, text: typeof r.text === 'function' ? r.text(f) : r.text});
    }
    if (f.syll >= 5) issues.push({pen:(f.syll - 4) * 4, text:f.syll + ' syllables is long for a brand name'});
    issues.sort((a,b) => b.pen - a.pen);
    const ease = Math.max(10, Math.min(100, 100 - issues.reduce((a,i) => a + i.pen, 0)));
    let reads = READS[L.code] ? READS[L.code](f) : null;
    if (reads) reads = reads.charAt(0).toUpperCase() + reads.slice(1);
    out[L.code] = {ease, issues, reads};
  }
  return out;
}

/* ---------- Transliteration ---------- */
function tokens(raw){
  let s = lettersOf(raw);
  if (s.length > 4 && /[^aeiouy]e$/.test(s) && /[aeiouy]/.test(s.slice(0,-2))) s = s.slice(0,-1);
  const V = 'aeiou', out = [];
  const DI = {sh:'sh', ch:'ch', th:'th', ph:'f', ck:'k', kh:'h', ts:'ts', tz:'ts', gh:'g'};
  const VD = {ee:['i'], oo:['u'], ou:['u'], ai:['a','i'], ay:['e','i'], ei:['e','i'], ey:['e','i'], au:['a','u'], oa:['o'], ea:['i'], ie:['i']};
  const pushC = c => { const last = out[out.length - 1]; if (last && last.c === c) return; out.push({c}); };
  let i = 0;
  while (i < s.length){
    const r = s.slice(i), two = r.slice(0,2), ch = r[0], nx = r[1] || '';
    if (r.startsWith('sch')){ pushC('sh'); i += 3; continue; }
    if (r.startsWith('tch')){ pushC('ch'); i += 3; continue; }
    if (two === 'qu'){ pushC('k'); out.push({c:'w'}); i += 2; continue; }
    if (DI[two]){ pushC(DI[two]); i += 2; continue; }
    if (VD[two] && !(two[1] === 'y' && V.includes(r[2] || '#'))){ VD[two].forEach(v => out.push({v})); i += 2; continue; }
    if (V.includes(ch)){ out.push({v:ch}); i++; continue; }
    if (ch === 'y'){
      const prevV = !out.length || !!out[out.length - 1].v;
      if (V.includes(nx) && prevV) out.push({c:'y'}); else out.push({v:'i'});
      i++; continue;
    }
    if (ch === 'c'){ pushC('eiy'.includes(nx) ? 's' : 'k'); i++; continue; }
    if (ch === 'q'){ pushC('k'); i++; continue; }
    if (ch === 'x'){ pushC('k'); out.push({c:'s'}); i++; continue; }
    if (ch === 'w'){ if (V.includes(nx) || nx === 'y') out.push({c:'w'}); else out.push({v:'u'}); i++; continue; }
    pushC(ch); i++;
  }
  const last = out[out.length - 1];
  if (last && last.v === 'i' && /(y|ee|ey)$/.test(s)) last.long = true;
  return out;
}
function units(tk){
  const u = [];
  for (let i = 0; i < tk.length; i++){
    const t = tk[i], n = tk[i + 1];
    if (t.c && n && n.v){ u.push({c:t.c, v:n.v, long:!!n.long}); i++; }
    else if (t.c) u.push({c:t.c});
    else u.push({c:'', v:t.v, long:!!t.long});
  }
  return u;
}

const TRANSLIT = {
  kana:{
    '':['ア','イ','ウ','エ','オ'], k:['カ','キ','ク','ケ','コ'], g:['ガ','ギ','グ','ゲ','ゴ'], s:['サ','シ','ス','セ','ソ'],
    z:['ザ','ジ','ズ','ゼ','ゾ'], t:['タ','ティ','トゥ','テ','ト'], d:['ダ','ディ','ドゥ','デ','ド'], n:['ナ','ニ','ヌ','ネ','ノ'],
    h:['ハ','ヒ','フ','ヘ','ホ'], b:['バ','ビ','ブ','ベ','ボ'], p:['パ','ピ','プ','ペ','ポ'], m:['マ','ミ','ム','メ','モ'],
    y:['ヤ','イ','ユ','イェ','ヨ'], r:['ラ','リ','ル','レ','ロ'], w:['ワ','ウィ','ウ','ウェ','ウォ'], f:['ファ','フィ','フ','フェ','フォ'],
    v:['ヴァ','ヴィ','ヴ','ヴェ','ヴォ'], sh:['シャ','シ','シュ','シェ','ショ'], ch:['チャ','チ','チュ','チェ','チョ'],
    j:['ジャ','ジ','ジュ','ジェ','ジョ'], ts:['ツァ','ツィ','ツ','ツェ','ツォ']
  },
  kanaFix:{si:'shi', zi:'ji', hu:'fu', yi:'i', wu:'u'},
  hangulInit:{k:15,g:0,t:16,d:3,p:17,b:7,f:17,v:7,s:9,z:12,sh:9,ch:14,j:12,ts:14,th:9,m:6,n:2,l:5,r:5,h:18,y:11,w:11,'':11},
  cyr:{b:'б',v:'в',w:'в',g:'г',d:'д',z:'з',k:'к',l:'л',m:'м',n:'н',p:'п',r:'р',s:'с',t:'т',f:'ф',h:'х',sh:'ш',ch:'ч',j:'дж',ts:'ц',th:'т',y:'й'},
  cyrV:{a:'а',e:'е',i:'и',o:'о',u:'у'}, cyrY:{a:'я',e:'е',i:'и',o:'ё',u:'ю'},
  grk:{b:'ΜΠ',v:'Β',w:'ΟΥ',g:'ΓΚ',d:'ΝΤ',z:'Ζ',k:'Κ',l:'Λ',m:'Μ',n:'Ν',p:'Π',r:'Ρ',s:'Σ',t:'Τ',f:'Φ',h:'Χ',sh:'Σ',ch:'ΤΣ',j:'ΤΖ',ts:'ΤΣ',th:'Θ',y:'Γ'},
  grkV:{a:'Α',e:'Ε',i:'Ι',o:'Ο',u:'ΟΥ'},
  heb:{b:'ב',v:'ב',w:'וו',g:'ג',d:'ד',h:'ה',z:'ז',ch:'צ׳',j:'ג׳',t:'ט',y:'י',k:'ק',l:'ל',m:'מ',n:'נ',s:'ס',p:'פ',f:'פ',ts:'צ',sh:'ש',th:'ת׳',r:'ר'},
  arb:{b:'ب',p:'ب',t:'ت',th:'ث',j:'ج',h:'ه',d:'د',r:'ر',z:'ز',s:'س',sh:'ش',f:'ف',v:'ف',k:'ك',g:'ج',l:'ل',m:'م',n:'ن',w:'و',y:'ي',ch:'تش',ts:'تس'}
};
const VI = {a:0, i:1, u:2, e:3, o:4};

function toKatakana(us){
  const T = TRANSLIT; let k = '', r = '';
  const kc = c => c === 'l' ? 'r' : c === 'th' ? 's' : (T.kana[c] ? c : '');
  const rom = (c, v) => { const x = c + v; return T.kanaFix[x] || x; };
  us.forEach(u => {
    const c = kc(u.c);
    if (u.v){ k += T.kana[c][VI[u.v]]; r += rom(c, u.v); if (u.long){ k += 'ー'; r += u.v; } }
    else if (c === 'n'){ k += 'ン'; r += 'n'; }
    else { const ev = (c === 't' || c === 'd') ? 'o' : (c === 'ch' || c === 'j') ? 'i' : 'u'; k += T.kana[c][VI[ev]]; r += rom(c, ev); }
  });
  return {text:k, roman:r};
}
function toHangul(us){
  const INI = TRANSLIT.hangulInit, syl = [];
  const vIdx = (c, v) => {
    if (c === 'y' || c === 'sh') return {a:2, e:7, i:20, o:12, u:17}[v];
    if (c === 'w') return {a:9, e:15, i:16, o:14, u:13}[v];
    return {a:0, e:5, i:20, o:8, u:13}[v];
  };
  us.forEach((u, idx) => {
    const prev = syl[syl.length - 1];
    if (u.v){
      if (u.c === 'l' && prev && prev.f === 0) prev.f = 8;
      syl.push({i: INI[u.c] != null ? INI[u.c] : 11, v: vIdx(u.c, u.v), f:0});
      return;
    }
    const c = u.c;
    if (prev && prev.f === 0){
      if (c === 'n'){ prev.f = 4; return; }
      if (c === 'm'){ prev.f = 16; return; }
      if (c === 'l'){ prev.f = 8; return; }
      if (c === 'r' && prev.v !== 18){ return; }
    }
    syl.push({i: INI[c] != null ? INI[c] : 11, v: (c === 'ch' || c === 'j' || c === 'sh') ? 20 : 18, f:0});
  });
  return {text: syl.map(s => String.fromCharCode(0xAC00 + (s.i * 21 + s.v) * 28 + s.f)).join('')};
}
function toCyrillic(us){
  const T = TRANSLIT; let o = '';
  us.forEach(u => {
    if (u.v){
      if (u.c === 'y') o += T.cyrY[u.v];
      else { if (u.c) o += T.cyr[u.c] || ''; o += (u.v === 'e' && !u.c) ? 'э' : T.cyrV[u.v]; }
    } else o += T.cyr[u.c] || '';
  });
  return {text: o.charAt(0).toUpperCase() + o.slice(1)};
}
function toGreek(us){
  const T = TRANSLIT; let o = '';
  us.forEach(u => {
    if (u.v){
      if (u.c === 'y') o += u.v === 'i' ? 'ΓΙ' : 'ΓΙ' + T.grkV[u.v];
      else { if (u.c) o += T.grk[u.c] || ''; o += T.grkV[u.v]; }
    } else o += T.grk[u.c] || '';
  });
  return {text: o.replace(/ΚΣ/g,'Ξ').replace(/ΠΣ/g,'Ψ')};
}
function toHebrew(us){
  const H = TRANSLIT.heb; let o = '';
  us.forEach((u, idx) => {
    const first = idx === 0, last = idx === us.length - 1;
    if (u.c) o += H[u.c] || '';
    if (!u.v) return;
    const v = u.v;
    if (!u.c) o += first ? {a:'א', e:'א', i:'אי', o:'או', u:'או'}[v] : 'א' + {a:'', e:'', i:'י', o:'ו', u:'ו'}[v];
    else if (last) o += {a:'ה', e:'ה', i:'י', o:'ו', u:'ו'}[v];
    else o += {a:'א', e:'', i:'י', o:'ו', u:'ו'}[v];
  });
  const lu = us[us.length - 1];
  if (lu && lu.c && !lu.v){
    const fin = {'מ':'ם', 'נ':'ן', 'צ':'ץ'}, chr = o.slice(-1);
    if (lu.c === 'f') o = o.slice(0,-1) + 'ף';
    else if (fin[chr]) o = o.slice(0,-1) + fin[chr];
  }
  return {text:o};
}
function toArabic(us){
  const A = TRANSLIT.arb; let o = '';
  us.forEach((u, idx) => {
    if (u.c) o += A[u.c] || '';
    if (!u.v) return;
    if (!u.c && idx === 0) o += {a:'ا', e:'إ', i:'إي', o:'أو', u:'أو'}[u.v];
    else o += {a:'ا', e:'ي', i:'ي', o:'و', u:'و'}[u.v];
  });
  return {text:o};
}
function renderScriptsData(raw){
  if (isInitialism(raw)){
    const t = String(raw).trim().toUpperCase();
    return [['he','Hebrew'],['ar','Arabic'],['ru','Russian'],['el','Greek'],['ja','Japanese'],['ko','Korean']]
      .map(([code,label]) => ({code, label, text:t, dir:'ltr', note:'Letter-and-number names usually stay in Latin script'}));
  }
  const us = units(tokens(raw));
  if (!us.length) return [];
  const ja = toKatakana(us);
  return [
    {code:'he', label:'Hebrew', text:toHebrew(us).text, dir:'rtl', note:'Reads right to left'},
    {code:'ar', label:'Arabic', text:toArabic(us).text, dir:'rtl', note:'Reads right to left; letters join'},
    {code:'ru', label:'Russian', text:toCyrillic(us).text, dir:'ltr', note:'Cyrillic'},
    {code:'el', label:'Greek', text:toGreek(us).text, dir:'ltr', note:'Shown in capitals, as on packaging'},
    {code:'ja', label:'Japanese', text:ja.text, dir:'ltr', note:'Katakana · ' + ja.roman},
    {code:'ko', label:'Korean', text:toHangul(us).text, dir:'ltr', note:'Hangul'}
  ];
}

/* ---------- Verdict ---------- */
function analyze(raw){
  const name = String(raw == null ? '' : raw).trim();
  const L = lettersOf(name);
  const hits = scanLandmines(name);
  const myths = MYTHS.filter(m => L && m.test(L));
  const pr = pronounce(name);
  const langs = LANGS.map(lg => {
    const p = pr[lg.code];
    const lh = hits.filter(h => h.lang === lg.code);
    const lm = myths.filter(m => m.lang === lg.code);
    let score = p.ease;
    if (lh.some(h => h.sev === 'red')) score = Math.min(score, 22);
    else if (lh.length) score = Math.min(score, 58);
    if (lm.length) score = Math.min(score, 78);
    const band = score >= 80 ? 'green' : score >= 55 ? 'amber' : 'red';
    return {code:lg.code, name:lg.name, ease:p.ease, issues:p.issues, reads:p.reads, hits:lh, myths:lm, score, band};
  });
  const reds = hits.filter(h => h.sev === 'red'), ambers = hits.filter(h => h.sev === 'amber');
  const hard = langs.filter(l => l.ease < 70);
  let verdict = 'Clear';
  if (reds.length) verdict = 'Rename';
  else if (ambers.length || hard.length >= 2 || langs.some(l => l.ease < 55)) verdict = 'Review';
  const scores = langs.map(l => l.score);
  const mean = scores.reduce((a,b) => a + b, 0) / scores.length, min = Math.min(...scores);
  let idx = Math.round(0.4 * mean + 0.6 * min);
  const band = {Rename:[5,45], Review:[50,79], Clear:[80,100]}[verdict];
  idx = Math.max(band[0], Math.min(band[1], idx));
  const order = LANGS.map(l => l.code);
  const free = [...langs].sort((a,b) => a.score - b.score || order.indexOf(a.code) - order.indexOf(b.code)).slice(0,5).map(l => l.code);

  const quote = h => '\u201c' + h.display + '\u201d';
  let reason = '';
  if (verdict === 'Rename'){
    const top = reds[0];
    const how = top.type === 'spelled' ? 'spelled aloud (' + top.spoken + ') runs into ' : top.type === 'exact' ? 'is ' : 'contains ';
    reason = top.langName + ': the name ' + how + quote(top) + ', ' + top.mean + '.';
    const rl = [...new Set(reds.map(h => h.langName))];
    reason += rl.length > 1 ? ' Red findings in ' + rl.length + ' languages (' + rl.join(', ') + '). Rename before you buy the domain.' : ' Rename, or keep it out of ' + top.langName + '-speaking markets.';
  } else if (verdict === 'Review'){
    const parts = [];
    if (ambers.length){
      const a = ambers[0];
      parts.push(a.langName + ': ' + TYPE_LABEL[a.type] + ' ' + quote(a) + ', ' + a.mean + '.');
      if (ambers.length > 1) parts.push((ambers.length - 1) + ' more amber finding' + (ambers.length > 2 ? 's' : '') + '.');
    }
    if (hard.length) parts.push('Hard to say in ' + hard.map(l => l.name).join(', ') + '.');
    parts.push('Usable with care. Check the findings with the markets you plan to enter.');
    reason = parts.join(' ');
  } else {
    const worst = [...langs].sort((a,b) => a.ease - b.ease)[0];
    reason = 'No landmines across 25 languages. Hardest to say in ' + worst.name + ' (' + worst.ease + '/100).';
    if (myths.length) reason += ' One popular myth noted below; it does not count against the name.';
  }
  return {name, hits, myths, langs, verdict, idx, reason, free, reds:reds.length, ambers:ambers.length,
          initialism:isInitialism(name), scripts:renderScriptsData(name)};
}
module.exports = { analyze, LANGS, LEXICON, TYPE_LABEL };
